with l as(select q.id,q.status,q.current_version_number,m.code micro_skill_code from public.questions q join public.micro_skills m on m.id=q.micro_skill_id where q.legacy_id between 5000311 and 5000350),v as(select q.id question_id,x.id from l q join public.question_versions x on x.question_id=q.id and x.version_number=q.current_version_number),c as(select v.question_id,count(a.id) choices,count(*) filter(where a.is_correct) correct_choices,max(a.sort_order) filter(where a.is_correct) correct_position from v join public.answer_choices a on a.question_version_id=v.id group by v.question_id)
select jsonb_build_object('questions',(select count(*) from l),'versions',(select count(*) from v),'choices',(select coalesce(sum(choices),0) from c),'correct_choices',(select coalesce(sum(correct_choices),0) from c),'micro_skills',(select count(distinct micro_skill_code) from l),'current_versions',(select count(*) from l where current_version_number=1),'questions_with_four_choices',(select count(*) from c where choices=4),'questions_with_one_correct_choice',(select count(*) from c where correct_choices=1),'statuses',(select array_agg(distinct status order by status) from l),'answer_a',(select count(*) from c where correct_position=1),'answer_b',(select count(*) from c where correct_position=2),'answer_c',(select count(*) from c where correct_position=3),'answer_d',(select count(*) from c where correct_position=4)) verification;
